import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第52章 挑一张","description":"","frontmatter":{},"headers":[],"relativePath":"第52章_挑一张.md","filePath":"第52章_挑一张.md"}'),o={name:"第52章_挑一张.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第52章-挑一张" tabindex="-1">第52章 挑一张 <a class="header-anchor" href="#第52章-挑一张" aria-label="Permalink to &quot;第52章 挑一张&quot;">​</a></h1><p>四月里有一天晚上，她忽然跟我说，我要开始删东西了。</p><p>我说，删什么。</p><p>她说，相册。</p><p>她说，我妈下个月要收我手机，她说要给我换个&quot;正经用的&quot;。</p><p>我说，那你备份了吗。</p><p>她说，备份了我妈也会翻。</p><p>她说，所以我现在删。</p><p>我说，那两千多张。</p><p>她说，嗯。</p><p>她说，我这两天在家就干这个，一张一张点删除。</p><p>她说，我删到凌晨三点，删了八百张。</p><p>她说，我发现我删得很熟练。</p><p>她说，我初中就开始删了，删相册里的、删聊天里的、删草稿箱里的。</p><p>她说，一个人要是删八百张不心疼，她不是不心疼，她是练过。</p><p>我坐在那儿，不知道说什么。</p><p>然后她说了一句让我坐直的话。</p><p>她说，有一批我删不下去。</p><p>我说，什么。</p><p>她说，合照。</p><p>她说，就是我退学以后没删干净的那批。</p><p>她说，那时候我在班级群里、在各种人家里、在各种吃饭的桌子上被拍下来。</p><p>她说，那些里有几张有你的。</p><p>我愣住了。</p><p>我说，我在那儿？</p><p>她说，你在。</p><p>她说，你从来不拍照，但你每次都在。</p><p>我说，哪几张。</p><p>她说，我先发给你，你别问我怎么留的。</p><p>然后她开始发图。</p><p>一张，两张，三张。</p><p>她发得很慢，中间隔很久，像是在核对。</p><p>一共十张。</p><p>十张里，有八张我根本没注意到自己在里面。</p><p>有一张是一桌人在火锅店，所有人看镜头，我在最边上，脸只有一半，正在低头给谁夹菜。</p><p>有一张是校门口一堆人比手势，我在后面第三排，被一个背包挡住半张脸。</p><p>有一张是某个人生日，大家都朝中间的蛋糕，我在最右边角落，手里拿着一杯饮料，眼睛看着别处。</p><p>十张发完了。</p><p>她说，你挑一张。</p><p>我说，什么。</p><p>她说，挑一张你留下来。</p><p>她说，我删之前得先给你。</p><p>她说，只给一次。</p><p>我说，为什么只有一张。</p><p>她说，因为我要是都给你，你就要开始一张一张看。</p><p>她说，你一张一张看，你就开始难受。</p><p>她说，你难受了我就得哄你。</p><p>她说，我下个月要走，我没有哄你的时间。</p><p>我看完了这五行字。</p><p>我承认我那时候心里第一反应不是被戳到，是一种很土的感动。</p><p>第二反应才是：她说的是实话。她真的没有。</p><p>我说，那我挑。</p><p>她说，你挑。你别挑我最好看的那张。</p><p>我说，为什么。</p><p>她说，因为我不好看的那几张我都不知道你在拍。</p><p>她说，我好看的那些，是我摆出来的。</p><p>她说，我摆出来的那些，跟我妈给我拍的一样，是给外面看的。</p><p>她说，我要是让你留一张摆出来的，你就记住了一个不是我。</p><p>我把那十张从头再看一遍。</p><p>看到第三遍的时候，我问了一句话。</p><p>我说，你以前删过一次吧。</p><p>她隔了很久。</p><p>她说，你怎么知道。</p><p>我说，因为这些图里有两张是别人发给你的。</p><p>我说，如果是你自己拍的，你当时就能删。</p><p>我说，别人发给你、你又存下来、存下来又删、删了又存，这种图才留到今天。</p><p>她不说话了。</p><p>过了大概三分钟，她说，我高三上删过一次。</p><p>她说，删完我难受了两个星期。</p><p>她说，后来我找班里一个人，让她把她手机里那两张发给我。</p><p>她说，我跟她说那是我妈让我删的。</p><p>她说，她说你妈真烦。</p><p>她说，她说得对。</p><p>我看着这一段，坐在床上把被子抓了一点上来。</p><p>我说，那你跟我一样。</p><p>她说，我不一样。</p><p>我说，哪里不一样。</p><p>她说，你能留。</p><p>她说，我不能。</p><p>她说，你的东西没有人查。</p><p>她说，我的手机每个月都要开一次。</p><p>那天晚上我才真正明白我们两个的处境差在哪。</p><p>不是她不喜欢。</p><p>是她手里拿不住任何东西。</p><p>我看到第四遍的时候，找到了。</p><p>那是一桌吃饭，镜头斜了，很多人的脸是虚的。</p><p>她在中间偏左，侧着的，正在笑。</p><p>那个笑不太好看。她眼睛眯着，牙露了一半，脖子往前伸了一点。</p><p>我在她对面，手伸过去，像在够什么东西。</p><p>中间隔着一锅，隔着一堆人的胳膊。</p><p>我说，第四张。</p><p>她说，那张？</p><p>我说，嗯。</p><p>她说，那张最糊。</p><p>我说，我知道。</p><p>她说，你眼睛没问题吗。</p><p>我说，没有。</p><p>她说，那你为什么挑这张。</p><p>我坐在那儿，看着这一行。</p><p>我很长时间没打。</p><p>后来我打的是：因为这张里你不知道我在拍。</p><p>她隔了很久才回。</p><p>久到我以为她睡了。</p><p>然后她说，你这个人真的很怪。</p><p>她说，别人都要我好看的。</p><p>她说，你要我不知道的。</p><p>我说，嗯。</p><p>她说，你别嗯。</p><p>她说，你嗯的时候我心里发慌。</p><p>那天晚上她把另外九张删了。</p><p>她没告诉我她删的过程，只发了一句：删完了。</p><p>我说，好。</p><p>她说，你不难受？</p><p>我说，我难受。</p><p>她说，那你倒是说一句人话。</p><p>我想了很久。</p><p>我说，你说你删八百张不心疼是因为练过。</p><p>我说，我这边不一样。</p><p>她说，怎么不一样。</p><p>我说，你删九张，我留一张。</p><p>我说，我这一辈子留东西的手法就是这样的。</p><p>那天夜里我做了两件事。</p><p>第一件，我把那张图存了两遍。一遍在相册，一遍在另一个我从来不用、也不会给别人看的文件夹里。</p><p>第二件事我做了，我后来一直没跟她说。</p><p>那十张里，其他九张我一张也没删。</p><p>她说只给一次，她说她只发了一次。</p><p>发出来的东西，收的人留多少，她管不着。</p><p>很多年以后我才明白，那天晚上我做的那第二件事，就是我们两个人这一辈子最根本的分别。</p><p>她这一辈子在把自己交出去之前，先删干净。</p><p>我这一辈子在别人删干净以后，再偷偷抄一份。</p><p>第二天她上线的时候，第一句话跟昨天一点关系都没有。</p><p>她说，我今天要去医院排队，人好多。</p><p>我说，几点去的。</p><p>她说，七点。</p><p>她说，我八点才吃上饭，旁边有个卖包子的摊，两块钱一个，还挺好吃。</p><p>我说，什么馅的。</p><p>她说，豆沙。</p><p>她说，我不爱吃甜的，但我今天吃完了。</p>',138)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
